import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Réglages","description":"","frontmatter":{},"headers":[],"relativePath":"fr/repair-station/settings.md","filePath":"fr/repair-station/settings.md"}'),s={name:"fr/repair-station/settings.md"};function o(i,t,n,c,l,u){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="reglages" tabindex="-1">Réglages <a class="header-anchor" href="#reglages" aria-label="Permalink to &quot;Réglages&quot;">​</a></h1><p>Chaque réglage de la Repair Station se modifie dans <code>/nay</code>, sur la page <strong>Repair Station</strong> (scope <code>nay_repair.config</code>). Les changements sont enregistrés dans la base et appliqués tout de suite à tous les joueurs. <code>config.lua</code> contient des valeurs de départ facultatives : elles s&#39;appliquent tant qu&#39;un réglage n&#39;a pas été changé dans <code>/nay</code>, et <strong>Réinitialiser</strong> revient à elles.</p><p>La colonne <strong>Dans /nay</strong> donne le nom affiché dans le panneau. La clé est le nom utilisé par <code>config.lua</code> et par l&#39;<a href="/fr/nay-lib/api">API HTTP</a>.</p><h2 id="general" tabindex="-1">Général <a class="header-anchor" href="#general" aria-label="Permalink to &quot;Général&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Activé</td><td><code>Enabled</code></td><td>oui / non</td><td>oui</td><td>Active ou désactive toutes les stations.</td></tr><tr><td>Compte de paiement</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> ou <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Où le prix est prélevé. <code>cash_then_bank</code> passe par la banque quand le liquide manque.</td></tr><tr><td>Remises par métier</td><td><code>JobDiscounts</code></td><td>liste, jusqu&#39;à 32</td><td>aucune</td><td>Remises pour un métier à partir d&#39;un grade.</td></tr><tr><td>Délai d&#39;attente (secondes)</td><td><code>CooldownSeconds</code></td><td>secondes, 0 à 3600</td><td>0</td><td>Attente minimale entre deux réparations du même joueur. 0 le désactive.</td></tr></tbody></table><p>Entrées de <strong>Remises par métier</strong> :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Métier</td><td><code>Job</code></td><td>texte, 1 à 32 caractères</td><td>Nom du métier, comme dans votre framework.</td></tr><tr><td>Grade minimum</td><td><code>MinGrade</code></td><td>nombre, 0 à 100</td><td>Grade le plus bas qui a la remise.</td></tr><tr><td>Remise (%)</td><td><code>Percent</code></td><td>nombre, 1 à 100</td><td>Remise en pourcentage. 100 rend la réparation gratuite.</td></tr></tbody></table><h2 id="prestations" tabindex="-1">Prestations <a class="header-anchor" href="#prestations" aria-label="Permalink to &quot;Prestations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Prestations de réparation</td><td><code>Services</code></td><td>liste, 1 à 8</td><td>Réparation moteur 250 $, Carrosserie et pneus 400 $, Réparation complète 700 $</td><td>Prestations proposées dans chaque station.</td></tr><tr><td>Prix selon les dégâts</td><td><code>PriceByDamage</code></td><td>oui / non</td><td>oui</td><td>Fait varier le prix avec les dégâts des parties réparées.</td></tr><tr><td>Prix minimum (%)</td><td><code>MinPricePercent</code></td><td>nombre, 0 à 100</td><td>20</td><td>Part la plus basse du prix de la prestation quand le prix suit les dégâts.</td></tr><tr><td>Refuser les véhicules intacts</td><td><code>RequireDamage</code></td><td>oui / non</td><td>oui</td><td>Refuse une prestation quand les parties qu&#39;elle répare sont intactes.</td></tr><tr><td>Classes de véhicules refusées</td><td><code>BlockedClasses</code></td><td>liste de classes de véhicules</td><td>vélos, bateaux, hélicoptères, avions, trains</td><td>Classes de véhicules refusées à la station.</td></tr></tbody></table><p>Entrées de <strong>Prestations de réparation</strong> :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Nom</td><td><code>Label</code></td><td>texte, jusqu&#39;à 32 caractères</td><td>Nom affiché dans le menu de réparation, l&#39;historique et les webhooks. Facultatif : vide, la prestation prend le nom des parties qu&#39;elle répare, dans la langue du serveur (Réparation moteur, Carrosserie et pneus, Réparation complète...).</td></tr><tr><td>Prix</td><td><code>Price</code></td><td>nombre, 0 à 1000000</td><td>Prix à dégâts maximaux, avant remises et pourcentage de la station.</td></tr><tr><td>Durée (secondes)</td><td><code>Seconds</code></td><td>nombre, 3 à 120</td><td>Durée de la réparation.</td></tr><tr><td>Répare le moteur</td><td><code>Engine</code></td><td>oui / non</td><td>Comprend le réservoir.</td></tr><tr><td>Répare la carrosserie</td><td><code>Body</code></td><td>oui / non</td><td>Comprend les vitres, les portes et les déformations.</td></tr><tr><td>Répare les pneus</td><td><code>Tyres</code></td><td>oui / non</td><td>Répare tous les pneus crevés.</td></tr></tbody></table><p>Avec <code>PriceByDamage</code> activé, le prix est le prix de la prestation multiplié par les dégâts les plus élevés des parties qu&#39;elle répare, jamais en dessous de <code>MinPricePercent</code> ni au-dessus de 100 pour cent. Le pourcentage de la station et la remise par métier s&#39;appliquent ensuite. Désactivé, le prix complet est toujours prélevé.</p><p>Les entrées de <strong>Classes de véhicules refusées</strong> ont un seul champ, <strong>Classe</strong> (<code>Class</code>), choisi par nom parmi les classes de véhicules de GTA.</p><h2 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations {#stations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Stations</td><td><code>Stations</code></td><td>liste, jusqu&#39;à 64</td><td>Hayes Autos, Sandy Shores, Paleto Bay</td><td>Les stations. Placées avec l&#39;<a href="/fr/repair-station/stations">éditeur de stations</a>.</td></tr></tbody></table><p>Les entrées se modifient plus facilement avec l&#39;<a href="/fr/repair-station/stations">éditeur de stations</a>, qui remplit ces champs pour vous :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Identifiant</td><td><code>Id</code></td><td>texte, 8</td><td>8 caractères (0 à 9, a à f), donnés par l&#39;éditeur. Doit être unique.</td></tr><tr><td>Nom</td><td><code>Label</code></td><td>texte, jusqu&#39;à 48 caractères</td><td>Affiché dans l&#39;invite, l&#39;historique et les webhooks. Facultatif.</td></tr><tr><td>Ouverte</td><td><code>Enabled</code></td><td>oui / non</td><td>Ferme une station sans la supprimer.</td></tr><tr><td>Position du véhicule</td><td><code>Coords</code></td><td>position et orientation</td><td>Là où les véhicules s&#39;arrêtent, avec l&#39;orientation.</td></tr><tr><td>Rayon (m)</td><td><code>Radius</code></td><td>mètres, 1,5 à 6</td><td>Distance maximale à la position pour qu&#39;un véhicule soit dans la station.</td></tr><tr><td>Prix (%)</td><td><code>PricePercent</code></td><td>nombre, 0 à 1000</td><td>Pourcentage appliqué à chaque prix dans cette station. 100 garde les prix.</td></tr><tr><td>Modèle du prop</td><td><code>Prop</code></td><td>texte, jusqu&#39;à 64 caractères</td><td>Prop posé à côté de la station. Facultatif.</td></tr><tr><td>Position du prop</td><td><code>PropCoords</code></td><td>position et orientation</td><td>Là où se trouve le prop. Facultatif.</td></tr><tr><td>Blip de la carte</td><td><code>Blip</code></td><td>oui / non</td><td>Affiche cette station sur la carte.</td></tr></tbody></table><h2 id="mecaniciens" tabindex="-1">Mécaniciens <a class="header-anchor" href="#mecaniciens" aria-label="Permalink to &quot;Mécaniciens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Métiers de mécanicien</td><td><code>MechanicJobs</code></td><td>liste, jusqu&#39;à 16</td><td><code>mechanic</code></td><td>Métiers comptés comme mécaniciens en service.</td></tr><tr><td>Limite de mécaniciens en service</td><td><code>MaxMechanicsOnDuty</code></td><td>nombre, 0 à 64</td><td>0</td><td>Les stations ferment tant que ce nombre de mécaniciens ou plus est en service. 0 ne les ferme jamais.</td></tr></tbody></table><p>Entrées de <strong>Métiers de mécanicien</strong> :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Métier</td><td><code>Job</code></td><td>texte, 1 à 32 caractères</td><td>Nom du métier, comme dans votre framework.</td></tr></tbody></table><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Afficher les blips</td><td><code>ShowBlips</code></td><td>oui / non</td><td>oui</td><td>Affiche sur la carte les stations qui ont un blip.</td></tr><tr><td>Icône du blip</td><td><code>BlipSprite</code></td><td>icône de blip</td><td>446</td><td>Choisie dans une liste visuelle d&#39;icônes. Un numéro peut toujours être saisi pour un blip personnalisé.</td></tr><tr><td>Couleur du blip</td><td><code>BlipColor</code></td><td>couleur de blip</td><td>47</td><td>Choisie dans une liste visuelle de couleurs.</td></tr><tr><td>Taille du blip</td><td><code>BlipScale</code></td><td>0,2 à 2</td><td>0,8</td><td>Taille du blip.</td></tr></tbody></table>',23)])])}const m=e(s,[["render",o]]);export{h as __pageData,m as default};
